import numpy as np

# jacobian and classify are defined for you.

def equilibria_and_types(f, guesses, tol=1e-12, max_iter=50):
    """Newton from each guess: [[[x, y], type], ...]."""
    out = []
    for g in guesses:
        z = np.asarray(g, dtype=float)
        for _ in range(max_iter):
            F = np.asarray(f(z), dtype=float)
            if np.max(np.abs(F)) < tol:
                break
            J = jacobian(f, z)
            if abs(np.linalg.det(J)) < 1e-14:
                raise ValueError("singular Jacobian")
            z = z - np.linalg.solve(J, F)
        else:
            raise ValueError("Newton did not converge")
        point = [round(float(v), 6) + 0.0 for v in z]
        out.append([point, classify(jacobian(f, z))])
    return out

