import numpy as np

def jacobian(f, z, h=1e-6):
    z = np.asarray(z, dtype=float)
    n = len(z)
    J = np.zeros((n, n))
    for k in range(n):
        e = np.zeros(n)
        e[k] = h
        J[:, k] = (np.asarray(f(z + e)) - np.asarray(f(z - e))) / (2 * h)
    return J

def classify(A, tol=1e-6):
    A = np.asarray(A, dtype=float)
    tau, det = float(np.trace(A)), float(np.linalg.det(A))
    if abs(det) <= tol:
        return "degenerate"
    if det < 0:
        return "saddle"
    if abs(tau) <= tol:
        return "centre"
    side = "stable" if tau < 0 else "unstable"
    return side + (" node" if tau * tau - 4 * det >= -tol else " spiral")
